BEGIN;

CREATE TEMP TABLE _cec_referendum_region_seed (
    event_key TEXT NOT NULL,
    case_number INTEGER NOT NULL,
    region_slug TEXT NOT NULL,
    eligible_voters BIGINT NOT NULL,
    yes_votes BIGINT NOT NULL,
    no_votes BIGINT NOT NULL,
    invalid_votes BIGINT NOT NULL,
    turnout_rate NUMERIC(7, 4) NOT NULL,
    source_url TEXT NOT NULL
) ON COMMIT DROP;


DO $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM _cec_referendum_region_seed seed
        LEFT JOIN public.regions region ON region.slug = seed.region_slug
        WHERE region.id IS NULL
    ) THEN
        RAISE EXCEPTION 'CEC referendum region seed references a missing canonical region';
    END IF;
END;
$$;

    id, question_id, region_id, eligible_voters, yes_votes, no_votes,
    invalid_votes, turnout_rate, source_name, source_url, is_public
)
SELECT
    MD5('cec-referendum:region-result:' || seed.event_key || ':' || seed.case_number || ':' || seed.region_slug)::UUID,
    MD5('cec-referendum:question:' || seed.event_key || ':' || seed.case_number)::UUID,
    region.id,
    seed.eligible_voters,
    seed.yes_votes,
    seed.no_votes,
    seed.invalid_votes,
    seed.turnout_rate,
    '中央選舉委員會',
    seed.source_url,
    TRUE
FROM _cec_referendum_region_seed seed
JOIN public.regions region ON region.slug = seed.region_slug
ON CONFLICT (question_id, region_id) DO UPDATE SET
    eligible_voters = EXCLUDED.eligible_voters,
    yes_votes = EXCLUDED.yes_votes,
    no_votes = EXCLUDED.no_votes,
    invalid_votes = EXCLUDED.invalid_votes,
    turnout_rate = EXCLUDED.turnout_rate,
    source_name = EXCLUDED.source_name,
    source_url = EXCLUDED.source_url,
    is_public = EXCLUDED.is_public,
    updated_at = NOW();

DO $$
DECLARE
    seeded_count BIGINT;
BEGIN
    SELECT COUNT(*) INTO seeded_count
    FROM public.referendum_region_results result
    WHERE result.id IN (
        SELECT MD5('cec-referendum:region-result:' || seed.event_key || ':' || seed.case_number || ':' || seed.region_slug)::UUID
        FROM _cec_referendum_region_seed seed
    );
    IF seeded_count <> 502 THEN
        RAISE EXCEPTION 'CEC referendum region seed validation failed: region results %', seeded_count;
    END IF;
END;
$$;

COMMIT;
